const {chromium}=require('playwright'),http=require('http'),fs=require('fs'),path=require('path'),assert=require('assert/strict');
const assets=path.resolve(__dirname,'../../internal/domaininit/assets'),out=process.env.SAMBAADM_DOMAIN_INIT_SCREENSHOTS||'/tmp/sambaadm-existing-ui';fs.mkdirSync(out,{recursive:true});
const server=http.createServer((req,res)=>{const file=path.join(assets,req.url==='/'?'index.html':req.url.replace('/assets/',''));if(!file.startsWith(assets)||!fs.existsSync(file)){res.writeHead(404).end();return;}res.setHeader('Content-Type',file.endsWith('.js')?'application/javascript':file.endsWith('.css')?'text/css':'text/html');res.end(fs.readFileSync(file));});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch();try{
const page=await browser.newPage({viewport:{width:1280,height:1200}});let unlocked=false,state='failed',starts=0,resumes=0;const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.route('**/api**',async route=>{const req=route.request(),url=new URL(req.url());let value={csrf:'test-csrf'},code=200;
if(url.pathname.endsWith('/unlock'))unlocked=true;
else if(!unlocked){code=401;value={error:'Введите код из консоли'};}
else if(url.pathname.endsWith('/plan')){const input=req.postDataJSON();assert.equal(input.mode,'existing');assert.equal(input.level,'auto');assert.equal(input.transferRoles,false);assert(!input.password);value={revision:'a'.repeat(64),checks:['Репозитории и пакеты доступны','Сервер готов к присоединению'],steps:['Присоединить RWDC','Дождаться каталога','Проверить и скопировать SYSVOL','Настроить панель и helper']};}
else if(url.pathname.endsWith('/start')){starts++;const input=req.postDataJSON();assert.equal(input.password,'PrivateSecretA1!');assert.equal(input.transferRoles,false);value={id:'a'.repeat(32),mode:'existing',realm:'corp.example',state:'queued'};}
else if(url.pathname.endsWith('/resume')){resumes++;const input=req.postDataJSON();assert.deepEqual(Object.keys(input).sort(),['id','password','username']);assert.equal(input.password,'PrivateSecretA1!');state='completed';value={id:'a'.repeat(32),state:'queued'};}
else if(url.pathname.endsWith('/status'))value={id:'a'.repeat(32),mode:'existing',realm:'corp.example',state,resumable:state==='failed',log:['Каталог и SYSVOL проверены','Настройка панели'],panelURL:'https://sambaadm.corp.example',report:{fsmo:[],directory:{users:620,groups:42,computers:108,ous:12,gpo:9},windowsTested:false}};
await route.fulfill({status:code,json:value});});
await page.goto('http://127.0.0.1:'+server.address().port);await page.getByLabel('Код доступа').fill('training-code');await page.getByRole('button',{name:'Открыть мастер'}).click();
await page.getByLabel('Сценарий установки').selectOption('existing');await page.getByLabel('DNS-имя домена / леса').fill('corp.example');await page.getByLabel('Имя контроллера',{exact:true}).fill('linux-dc1');await page.getByLabel('Постоянный IPv4 сервера').fill('192.0.2.20');await page.getByLabel('Исходный RWDC').fill('win-dc1.corp.example');await page.getByLabel('DNS-пересыльщик').fill('192.0.2.53');await page.getByLabel('HTTPS-имя панели').fill('sambaadm.corp.example');await page.getByLabel('Новая служебная запись панели').fill('sadm-linuxdc1');assert(!await page.getByRole('checkbox').isChecked());assert.equal(await page.getByLabel('Сайт RWDC').inputValue(),'');await page.locator('.di-shell').screenshot({path:path.join(out,'existing-parameters.png')});
await page.setViewportSize({width:390,height:844});assert(!await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth));await page.setViewportSize({width:1280,height:1200});
await page.getByRole('button',{name:'Далее: проверить сервер'}).click();await page.getByRole('button',{name:'Проверить сервер и пакеты'}).click();await page.getByText('Сервер готов к присоединению',{exact:true}).waitFor();await page.getByRole('button',{name:'Далее',exact:true}).click();await page.getByLabel('Учётная запись для присоединения').fill('Administrator@corp.example');await page.getByLabel('Пароль доменной учётной записи').fill('PrivateSecretA1!');await page.getByLabel('Повторите пароль').fill('PrivateSecretA1!');await page.getByRole('checkbox').check();await page.getByRole('button',{name:'Присоединить RWDC',exact:true}).click();await page.getByRole('button',{name:'Продолжить настройку панели'}).waitFor();assert(!JSON.stringify(await page.evaluate(()=>({...sessionStorage}))).includes('PrivateSecret'));await page.reload();await page.getByRole('button',{name:'Продолжить настройку панели'}).waitFor();assert.equal(starts,1);
await page.getByLabel('Доменная учётная запись',{exact:true}).fill('Administrator@corp.example');await page.getByLabel('Пароль',{exact:true}).fill('PrivateSecretA1!');await page.getByRole('button',{name:'Продолжить настройку панели'}).click();await page.getByRole('link',{name:'Инструкция по выводу Windows DC'}).waitFor();assert.equal(resumes,1);assert.equal(starts,1);await page.getByText('620',{exact:true}).waitFor();await page.locator('.di-shell').screenshot({path:path.join(out,'existing-complete.png')});assert.deepEqual(errors,[]);console.log('PASS existing-domain wizard, default FSMO skip, auto site/level, password isolation, resume without rejoin, report and mobile; screenshots:',out);
}finally{await browser.close();server.close();}})().catch(e=>{console.error(e);server.close();process.exitCode=1;});
